from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1400,'height':950}, accept_downloads=True); pg.add_init_script('window.__PAYCURE_TEST__=true')
    errs=[]; pg.on('pageerror',lambda e:errs.append('PAGEERR '+str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type=='error' and '403' not in m.text and 'ERR_TUNNEL_CONNECTION_FAILED' not in m.text and 'font' not in m.text.lower() else None)
    pg.on('dialog', lambda d: d.accept('Test run'))
    pg.goto('file://' + __import__('os').path.abspath('dist/paycure-standalone.html') + ''); pg.wait_for_timeout(800)
    pg.screenshot(path='/tmp/n_landing.png')
    pg.evaluate("PCX.setView('onboard')"); pg.wait_for_timeout(200)
    pg.click('[data-act="ob-next"]'); print('toast role:', pg.inner_text('#toast'))
    pg.select_option('[data-ob="role"]','Employment attorney'); pg.click('[data-act="ob-next"]')
    pg.fill('[data-ob="company"]','Pacific Coast Fresh, Inc.'); pg.fill('[data-ob="employees"]','500'); pg.fill('[data-ob="locations"]','Oxnard, Salinas'); pg.check('[data-obi="Agriculture"]'); pg.click('[data-act="ob-next"]')
    pg.select_option('[data-ob="payroll"]','ADP'); pg.wait_for_timeout(100); pg.click('[data-act="ob-next"]')
    pg.select_option('[data-ob="purpose"]','notice'); pg.wait_for_timeout(100); pg.fill('[data-ob="noticeDate"]','2024-03-01'); pg.click('[data-act="ob-next"]'); pg.wait_for_timeout(100)
    pg.screenshot(path='/tmp/n_onboard.png')
    pg.click('[data-act="ob-finish"][data-to="demo"]'); pg.wait_for_selector('text=Likely exposure', timeout=60000)
    # findings workflow
    pg.evaluate("PCX.setView('findings')"); pg.click('tr[data-finding] >> nth=0'); pg.wait_for_timeout(300)
    pg.select_option('#fs-s','dismissed'); pg.click('[data-act="fs-save"]'); print('dismiss w/o reason:', pg.inner_text('#toast'))
    pg.fill('#fs-r','Employee chose to take a late meal; acknowledgment on file.'); pg.click('[data-act="fs-save"]'); pg.wait_for_timeout(300)
    pg.screenshot(path='/tmp/n_finding.png'); print('ledger shown:', 'Calculation ledger' in pg.inner_text('#drawer-body'))
    pg.click('[data-act="task-new"]'); pg.click('#drawer-close')
    pg.evaluate("PCX.setView('workers')"); pg.click('tr[data-worker] >> nth=0'); pg.wait_for_timeout(400); print('worker why:', pg.inner_text('#drawer-body')[:60].replace('\n',' ')); pg.click('#drawer-close')
    pg.evaluate("PCX.setView('paga')"); pg.wait_for_timeout(300); print('paga statute pre2024 selected:', pg.eval_on_selector('#pg-reg','e=>e.value')); pg.check('#pg-ex'); pg.wait_for_timeout(200); pg.screenshot(path='/tmp/n_paga.png')
    pg.evaluate("PCX.setView('remediation')"); pg.click('[data-act="task-seed"]'); pg.wait_for_timeout(200); print('tasks:', pg.locator('[data-tk][data-f="status"]').count())
    pg.evaluate("PCX.setView('reports')")
    for r in ['executive','paga','attorney','quality']:
        with pg.expect_download() as dl: pg.click(f'[data-act="rpt"][data-r="{r}"]')
        print('report', dl.value.suggested_filename)
    with pg.expect_download() as dl: pg.click('[data-act="xlsx"]')
    x=dl.value; x.save_as('/tmp/out.xlsx'); print('xlsx', x.suggested_filename)
    pg.click('[data-act="rpt-prev"][data-r="detailed"]'); pg.wait_for_timeout(500)
    for v in ['quality','trail','plans','rules','ask','home','exec','detective','scenarios','settlement','diligence','documents','review','attest','steps','monitor','method','law','import']:
        pg.evaluate(f"PCX.setView('{v}')"); pg.wait_for_timeout(250)
        if v in ('quality','trail','plans','home','rules'): pg.screenshot(path=f'/tmp/n_{v}.png')
    pg.click('#as-fab'); pg.wait_for_timeout(200); pg.click('#as-panel [data-act="as-ask"] >> nth=0'); pg.wait_for_timeout(200); print('assistant w/o AI:', pg.inner_text('#toast'))
    print('ERRORS', errs[:10]); b.close()
